import{_ as t,o as r,c as s,ae as a}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"TermLens","description":"","frontmatter":{},"headers":[],"relativePath":"glossaries/termlens.md","filePath":"glossaries/termlens.md"}'),o={name:"glossaries/termlens.md"};function n(i,e,l,h,g,d){return r(),s("div",null,e[0]||(e[0]=[a('<h1 id="termlens" tabindex="-1">TermLens <a class="header-anchor" href="#termlens" aria-label="Permalink to &quot;TermLens&quot;">​</a></h1><p>TermLens is Supervertaler&#39;s inline terminology display. It shows the source text of the current segment word by word, with glossary translations directly underneath each matched term.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>When you select a segment, TermLens analyses the source text against all active glossaries and displays the result in a visual layout:</p><ul><li><strong>Matched words</strong> appear with their glossary translation underneath</li><li><strong>Unmatched words</strong> are shown in light text so you can read the full source sentence in context</li><li><strong>Project glossary</strong> matches appear in pink; <strong>Background glossary</strong> matches appear in blue</li><li><strong>Non-translatable</strong> terms (if configured) are shown in a distinct style</li></ul><p>This gives you an at-a-glance overview of every term in the segment that has a glossary entry — without having to hover or click anything.</p><h2 id="where-to-find-it" tabindex="-1">Where to find it <a class="header-anchor" href="#where-to-find-it" aria-label="Permalink to &quot;Where to find it&quot;">​</a></h2><p>TermLens appears in two places:</p><ol><li><strong>Below the grid</strong> — the &quot;TermLens&quot; tab in the bottom panel (toggle with <strong>View → TermLens Under Grid</strong>)</li><li><strong>In the Match Panel</strong> — the right-side panel that also shows TM matches</li></ol><p>Both instances update simultaneously when you navigate to a new segment.</p><h2 id="inserting-terms" tabindex="-1">Inserting terms <a class="header-anchor" href="#inserting-terms" aria-label="Permalink to &quot;Inserting terms&quot;">​</a></h2><p>You can insert a glossary translation from TermLens into your target text in three ways:</p><h3 id="click-to-insert" tabindex="-1">Click to insert <a class="header-anchor" href="#click-to-insert" aria-label="Permalink to &quot;Click to insert&quot;">​</a></h3><p>Click any translation shown under a source word. The translation is inserted at the cursor position in the target field.</p><h3 id="keyboard-shortcuts-alt-1-through-alt-9" tabindex="-1">Keyboard shortcuts (Alt+1 through Alt+9) <a class="header-anchor" href="#keyboard-shortcuts-alt-1-through-alt-9" aria-label="Permalink to &quot;Keyboard shortcuts (Alt+1 through Alt+9)&quot;">​</a></h3><p>Each matched term in TermLens is assigned a numbered badge. Press <strong>Alt+1</strong> to insert the first match, <strong>Alt+2</strong> for the second, and so on.</p><p><strong>Double-tap</strong> for terms 10 and above: press <strong>Alt+1, Alt+1</strong> quickly to insert term 11, <strong>Alt+2, Alt+2</strong> for term 22, etc.</p><blockquote><p><strong>Note:</strong> Alt+0 is reserved for the Compare Panel. TermLens numbering starts at 1.</p></blockquote><h3 id="right-click-menu" tabindex="-1">Right-click menu <a class="header-anchor" href="#right-click-menu" aria-label="Permalink to &quot;Right-click menu&quot;">​</a></h3><p>Right-click a term in TermLens to:</p><ul><li><strong>Insert</strong> the translation</li><li><strong>Edit</strong> the glossary entry</li><li><strong>Delete</strong> the glossary entry</li></ul><h2 id="font-settings" tabindex="-1">Font settings <a class="header-anchor" href="#font-settings" aria-label="Permalink to &quot;Font settings&quot;">​</a></h2><p>You can customise the TermLens font independently from the grid font:</p><ol><li>Go to <strong>Settings → View Settings → TermLens Font Settings</strong></li><li>Choose font family, size (6–16 pt), and bold/normal weight</li><li>Changes apply immediately to both TermLens instances</li></ol><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Press <strong>F5</strong> to force a refresh if matches appear to be missing.</li><li>TermLens respects glossary activation — only terms from activated glossaries are shown.</li><li>If you have many glossaries, designate one as the <strong>Project glossary</strong> (shown in pink) to make its terms stand out.</li></ul><h2 id="termlens-for-trados" tabindex="-1">TermLens for Trados <a class="header-anchor" href="#termlens-for-trados" aria-label="Permalink to &quot;TermLens for Trados&quot;">​</a></h2><p>A standalone version of TermLens is also available as a plugin for <strong>Trados Studio 2024+</strong>. It reads the same SQLite termbase format used by Supervertaler and displays terminology matches directly inside the Trados editor.</p><p>→ <a href="https://github.com/michaelbeijer/TermLens" target="_blank" rel="noreferrer">TermLens for Trados on GitHub</a></p><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./basics.html">Glossary Basics</a></li><li><a href="./highlighting.html">Term Highlighting</a></li><li><a href="./../editor/keyboard-shortcuts.html">Keyboard Shortcuts</a></li></ul>',32)]))}const u=t(o,[["render",n]]);export{m as __pageData,u as default};
